    recentCharacters: firstConfig.recentCharacters || 'None',
    websiteVisualStyle: site.visualStyle || '',
    websiteLanguage: site.language || ''
  }
}];

// Rotate Backup Strategy LLM Key on Failure — iterates through ALL backup keys
let staticData = $getWorkflowStaticData('global');
const execId = String($execution.id || '');
if (staticData.strategyBackupExecId !== execId) {
  staticData.strategyBackupExecId = execId;
  staticData.strategyBackupAttempts = 0;
}
const configNode = $('Config: Strategy Backup LLM Master').first().json || {};
const keys = configNode.keys || [];
const totalKeys = keys.length || 15;

if (staticData.strategyBackupAttempts === undefined) {
  staticData.strategyBackupAttempts = 0;
}
if (staticData.backupStrategyLlmIndex === undefined) {
  staticData.backupStrategyLlmIndex = 0;
}

staticData.strategyBackupAttempts += 1;

if (staticData.strategyBackupAttempts > totalKeys) {
  console.log(`[STRATEGY BACKUP EXHAUSTED] All ${totalKeys} backup keys failed. Moving to fallback brief.`);
  staticData.strategyBackupAttempts = 0;
  staticData.backupStrategyLlmIndex = 0;
  return [{ json: { backupExhausted: true } }];
}

staticData.backupStrategyLlmIndex = (staticData.backupStrategyLlmIndex + 1) % totalKeys;
console.log(`[STRATEGY BACKUP RETRY] Attempt ${staticData.strategyBackupAttempts}/${totalKeys}: Rotating to key index ${staticData.backupStrategyLlmIndex}`);
return [{ json: { backupExhausted: false } }];

// Filter: My Chat Only — authenticate + normalize website payload
// (voice, speed, volume, music, subtitles, YouTube & Google Sheets) with strict prompt validation
const raw      = $input.first().json || {};
const headers  = raw.headers || {};
const body     = raw.body || raw;
const query    = raw.query || {};
const settings = body.settings || {};

// ---------- SECURITY ----------
const VALID_SECRET = 's-vshorts-sec-9a8b7c6d5e4f3a2b1c0';
const providedSecret = headers['x-webhook-secret']
  || headers['X-Webhook-Secret']
  || body.webhookSecret
  || body.secretKey
  || query.secret
  || raw.webhookSecret;

if (providedSecret !== VALID_SECRET) {
  throw new Error('Unauthorized: Invalid webhook security secret');
}

// ---------- PROMPT (OPTIONAL for template workflow - blank means auto-select topic) ----------
const rawPrompt = body.prompt || body.message || body.rawUserInput
  || query.prompt || query.message || raw.prompt || '';

const prompt = typeof rawPrompt === 'string' ? rawPrompt.trim() : (rawPrompt ? String(rawPrompt).trim() : '');

// ---------- LANGUAGE (typed instruction wins over website default) ----------
const lower = prompt.toLowerCase();
let language = body.language || query.language || settings.language || 'Hinglish';

if (lower.includes('in english') || lower.includes('english only') || lower.includes('only english') || lower.includes('english mein')) {
  language = 'English';
} else if (lower.includes('in hinglish') || lower.includes('hinglish only') || lower.includes('only hinglish')) {
  language = 'Hinglish';
} else if (lower.includes('in hindi') || lower.includes('hindi only') || lower.includes('only hindi') || lower.includes('hindi mein')) {
  language = 'Hindi';
}

// ---------- HELPERS ----------
const firstDefined = (...vals) => {
  for (const v of vals) if (v !== undefined && v !== null && v !== '') return v;
  return undefined;
};
const clampNum = (val, min, max, fallback) => {
  const n = Number(val);
  if (!isFinite(n)) return fallback;
  return Math.max(min, Math.min(max, n));
};

// ---------- VOICE & SPEED ----------
const voiceId          = firstDefined(body.voiceId, query.voiceId, settings.voiceId) || 'adam';
const elevenLabsVoiceId = String(firstDefined(body.elevenLabsVoiceId, query.elevenLabsVoiceId, settings.elevenLabsVoiceId) || '').trim();

const voiceSpeed = clampNum(
  firstDefined(body.voiceSpeed, query.voiceSpeed, settings.voiceSpeed),
  0.5, 4, 1.20
);

let rawVoiceVolume = body.voiceVolume;
if (rawVoiceVolume === undefined) rawVoiceVolume = query.voiceVolume;
if (rawVoiceVolume === undefined) rawVoiceVolume = settings.voiceVolume;
const voiceVolume = clampNum(rawVoiceVolume, 0, 2.0, 1.0);

// ---------- MUSIC (0 is a valid choice = muted) ----------
const musicId       = firstDefined(body.musicId, query.musicId, settings.musicId) || 'mystery2';
const musicTrackUrl = String(firstDefined(body.musicTrackUrl, query.musicTrackUrl, settings.musicTrackUrl) || '').trim();

let rawVolume = body.musicVolume;
if (rawVolume === undefined) rawVolume = query.musicVolume;
if (rawVolume === undefined) rawVolume = settings.musicVolume;
const musicVolume = clampNum(rawVolume, 0, 0.4, 0.08);

// ---------- SUBTITLES ----------
let subtitleSettings = firstDefined(body.subtitleSettings, query.subtitleSettings, settings.subtitleSettings) || null;
if (typeof subtitleSettings === 'string') {
  try { subtitleSettings = JSON.parse(subtitleSettings); } catch (e) { subtitleSettings = null; }
}
if (subtitleSettings && typeof subtitleSettings !== 'object') subtitleSettings = null;

// ---------- GOOGLE OAUTH: YOUTUBE & SHEETS (PASSTHROUGH) ----------
const autoUploadToYouTube     = body.autoUploadToYouTube !== undefined ? !!body.autoUploadToYouTube : (query.autoUploadToYouTube !== undefined ? !!query.autoUploadToYouTube : (settings.autoUploadToYouTube !== undefined ? !!settings.autoUploadToYouTube : false));
const userYouTubeAccessToken  = String(firstDefined(body.userYouTubeAccessToken, query.userYouTubeAccessToken, settings.userYouTubeAccessToken) || '').trim();
const userYouTubeChannelTitle = String(firstDefined(body.userYouTubeChannelTitle, query.userYouTubeChannelTitle, settings.userYouTubeChannelTitle) || '').trim();
const userYouTubeChannelId    = String(firstDefined(body.userYouTubeChannelId, query.userYouTubeChannelId, settings.userYouTubeChannelId) || '').trim();

const autoLogToSheet          = body.autoLogToSheet !== undefined ? !!body.autoLogToSheet : (query.autoLogToSheet !== undefined ? !!query.autoLogToSheet : (settings.autoLogToSheet !== undefined ? !!settings.autoLogToSheet : true));
const userSheetAccessToken    = String(firstDefined(body.userSheetAccessToken, query.userSheetAccessToken, settings.userSheetAccessToken) || '').trim();
const userSpreadsheetId       = String(firstDefined(body.userSpreadsheetId, query.userSpreadsheetId, settings.userSpreadsheetId) || '').trim();
const userSheetName           = String(firstDefined(body.userSheetName, query.userSheetName, settings.userSheetName) || 'Production Log').trim();

// ---------- PRIVACY ----------
const rawPrivacy = String(firstDefined(body.privacyStatus, body.privacy, settings.privacyStatus, settings.privacy, query.privacyStatus, query.privacy) || 'public').toLowerCase();
const privacyStatus = ['public', 'private', 'unlisted'].includes(rawPrivacy) ? rawPrivacy : 'public';

// ---------- IDENTITY ----------
const threadId    = firstDefined(body.threadId, query.threadId, raw.threadId) || ('thread-' + Date.now());
const sessionId   = firstDefined(body.sessionId, query.sessionId, raw.sessionId) || 'session-default';
const callbackUrl = firstDefined(body.callbackUrl, query.callbackUrl, raw.callbackUrl)
  || 'https://bangai.netlify.app/.netlify/functions/story-approval';

return [{
  json: {
    rawUserInput: prompt,
    prompt: prompt,
    threadId: threadId,
    sessionId: sessionId,
    callbackUrl: callbackUrl,
    voiceId: voiceId,
