// Rotate Zvid Key & Build Multi-Track Payload with Dynamic Frontend Subtitles & Audio
const staticData = $getWorkflowStaticData('global');

// Reset CloudConvert attempts upon successful transition
try {
  staticData.cloudConvertAttempts = 0;
} catch(e) {}

let keys = [];
try {
  keys = $('Config: Zvid Master').first().json.keys || [];
} catch(e) {}

if (keys.length === 0) {
  throw new Error('[Rotate Zvid Key] No Zvid keys configured in Config: Zvid Master.');
}

if (staticData.zvidKeyIndex === undefined) {
  staticData.zvidKeyIndex = 0;
}

const currentKeyIndex = staticData.zvidKeyIndex % keys.length;
const currentKey = keys[currentKeyIndex];

let allScenes = [];
try { allScenes = $('Merge Hybrid Scenes').all(); } catch(e) {}
if (!allScenes || allScenes.length === 0) {
  allScenes = $input.all();
}
const scenes = allScenes.sort((a, b) => (a.json?.sceneNumber || 0) - (b.json?.sceneNumber || 0));

// Dual audio URLs from CloudConvert (search from newest to oldest run for successful tasks)
let ccTasks = [];
try {
  const allCcRuns = $('Convert Dual Voice to Pure MP3 (CloudConvert)').all();
  for (let i = allCcRuns.length - 1; i >= 0; i--) {
    if (allCcRuns[i]?.json?.data?.tasks && allCcRuns[i].json.data.tasks.length > 0) {
      ccTasks = allCcRuns[i].json.data.tasks;
      break;
    }
  }
} catch (e) {
  try {
    ccTasks = $('Convert Dual Voice to Pure MP3 (CloudConvert)').first().json.data?.tasks || [];
  } catch(e2) {}
}

const part1File = ccTasks.find(t => t.name === 'export-part1')?.result?.files?.[0]?.url;
const part2File = ccTasks.find(t => t.name === 'export-part2')?.result?.files?.[0]?.url;

// 5 Visuals (15s each = 75s total)
const visuals = scenes.map((s, idx) => {
  const v = {
    type: 'VIDEO',
    id: 'scene' + (idx + 1),
    src: s.json.url || s.json.videoUrl,
    resize: 'cover',
    volume: 0,
    enterBegin: idx * 15,
    exitEnd: (idx + 1) * 15
  };
  if (idx < 4) {
    v.transition = 'fade';
    v.transitionDuration = 0.5;
    v.transitionId = 'scene' + (idx + 2);
  }
  return v;
});

// Dynamic Settings Extraction from Website / Approvals
let site = {};
try { site = $('Filter: My Chat Only').first().json || {}; } catch(e) {}
const userCustom = {};

// 1. Voice Volume
const rawVoiceVol = userCustom.voiceVolume !== undefined ? userCustom.voiceVolume : site.voiceVolume;
const numVoiceVol = Number(rawVoiceVol);
const safeVoiceVol = isFinite(numVoiceVol) ? Math.max(0, Math.min(2.0, numVoiceVol)) : 1.0;

// 2. Music Track & Volume
const MUSIC_MAP = {
  synth: 'https://bangai.netlify.app/music/synth.mp3',
  ambient: 'https://bangai.netlify.app/music/ambient.mp3',
  mystery2: 'https://bangai.netlify.app/music/mystery2.mp3',
  indian: 'https://bangai.netlify.app/music/indian.mp3',
  action: 'https://bangai.netlify.app/music/action.mp3',
  piano: 'https://bangai.netlify.app/music/piano.mp3',
  playful: 'https://bangai.netlify.app/music/playful.mp3',
  epic: 'https://bangai.netlify.app/music/epic.mp3'
};
const DEFAULT_BG_MUSIC = 'https://bangai.netlify.app/music/mystery2.mp3';

const chosenMusicId = String(userCustom.musicId || site.musicId || 'mystery2').toLowerCase();
let bgMusicUrl = userCustom.musicTrackUrl || site.musicTrackUrl || MUSIC_MAP[chosenMusicId] || '';
if (!bgMusicUrl && chosenMusicId !== 'none') {
  bgMusicUrl = DEFAULT_BG_MUSIC;
}

const rawMusicVol = userCustom.musicVolume !== undefined ? userCustom.musicVolume : site.musicVolume;
const numMusicVol = Number(rawMusicVol);
const safeMusicVol = isFinite(numMusicVol) ? Math.max(0, Math.min(0.4, numMusicVol)) : 0.08;

const audios = [
  {
    src: part1File,
    volume: safeVoiceVol,
    enter: 0,
    exit: 45
  },
  {
    src: part2File,
    volume: safeVoiceVol,
    enter: 45,
    exit: 75
  }
];

if (bgMusicUrl && chosenMusicId !== 'none' && safeMusicVol > 0) {
  audios.push({
    src: bgMusicUrl,
    volume: safeMusicVol,
    enter: 0,
    exit: 75
  });
}

// ── Smart Paced & Real-Time Synchronized Subtitle Captions ──
const rawSpeed = userCustom.voiceSpeed !== undefined ? userCustom.voiceSpeed : site.voiceSpeed;
let voiceSpeed = 1.20;
if (rawSpeed !== undefined) {
  const numSpeed = Number(rawSpeed);
  if (isFinite(numSpeed) && numSpeed > 0) voiceSpeed = Math.max(0.5, Math.min(4.0, numSpeed));
}

const lang = String(site.language || '').toLowerCase();
const allVoText = scenes.map(s => s.json?.voiceoverText || '').join(' ');
const hasDevanagari = /[\u0900-\u097F]/.test(allVoText) || lang.includes('hindi') || lang.includes('hinglish');

// Calibrate speech rate to ElevenLabs model
const wordsPerSec = (hasDevanagari ? 2.30 : 2.70) * (voiceSpeed / 1.0);
const charsPerSec = (hasDevanagari ? 12.2 : 15.0) * (voiceSpeed / 1.0);

const captions = [];

scenes.forEach((s, idx) => {
  const sceneStart = idx * 15;
  const rawText = (s.json?.voiceoverText || '').trim();
  if (!rawText) return;

  // 1. Segment text into natural rhythmic subtitle chunks (4-8 words each)
  const rawSentences = rawText.split(/(?<=[।!?\.\n])\s+/).map(t => t.trim()).filter(Boolean);
  const chunks = [];
  for (const sent of rawSentences) {
    const words = sent.split(/\s+/);
    if (words.length > 8 && /[,;，、]/.test(sent)) {
      const subParts = sent.split(/(?<=[,;，、])\s+/).map(t => t.trim()).filter(Boolean);
      chunks.push(...subParts);
    } else if (words.length > 10) {
      const mid = Math.ceil(words.length / 2);
      chunks.push(words.slice(0, mid).join(' '));
      chunks.push(words.slice(mid).join(' '));
    } else {
      chunks.push(sent);
    }
  }

  if (chunks.length === 0) chunks.push(rawText);

  // 2. Calibrate speech duration to fit scene
  const totalWords = rawText.split(/\s+/).length;
  const totalChars = rawText.length;
  const estFromWords = totalWords / wordsPerSec;
  const estFromChars = totalChars / charsPerSec;
  const rawEstDuration = (estFromWords + estFromChars) / 2;

  // Fit speech within 9.5s to 14.2s of the 15s visual slot
  const sceneSpeechDuration = Math.min(14.2, Math.max(9.5, rawEstDuration));

  // Natural micro-pause between phrases
  const pauseBetween = 0.08;
  const totalPauseTime = (chunks.length - 1) * pauseBetween;
  const activeSpeechTime = Math.max(5.0, sceneSpeechDuration - totalPauseTime);

  // Weight each chunk proportionally by character & word count
  const chunkWeights = chunks.map(c => {
    const cWords = c.split(/\s+/).length;
    const cChars = c.length;
    return (cWords / totalWords) * 0.5 + (cChars / totalChars) * 0.5;
  });

  let cursor = sceneStart;
  chunks.forEach((chunk, cIdx) => {
    const chunkDur = activeSpeechTime * chunkWeights[cIdx];
    const start = Number(cursor.toFixed(2));
    const end = Number((cursor + chunkDur).toFixed(2));
    captions.push({
      start: start,
      end: end,
      text: chunk
    });
    cursor = end + pauseBetween;
  });
});

// Dynamic Subtitle Configuration from User Settings
const rawSubs = userCustom.subtitleSettings || site.subtitleSettings || {};

let resolvedFontFamily = rawSubs.fontFamily || (rawSubs.font && rawSubs.font.family) || (hasDevanagari ? 'Noto Sans Devanagari' : 'Montserrat');
if (hasDevanagari && ['Montserrat', 'Inter', 'Bebas Neue', 'Luckiest Guy', 'Bangers', 'Oswald', 'Permanent Marker'].includes(resolvedFontFamily)) {
  resolvedFontFamily = 'Noto Sans Devanagari';
}

const subStyle = String(rawSubs.style || rawSubs.presetId || '').toLowerCase();
const hasBox = !!(rawSubs.boxColor || subStyle.includes('box'));
const isOneWord = subStyle.includes('one-word') || rawSubs.maxWordsPerLine === 1;

let animationType = 'karaoke';
if (hasBox) {
  animationType = 'highlight';
} else if (isOneWord) {
  animationType = 'one-word';
}

const activeWordColor = rawSubs.wordColor || (rawSubs.activeWord && rawSubs.activeWord.color) || '#FFE500';
const activeWordObj = { color: activeWordColor };
if (hasBox) {
  activeWordObj.background = rawSubs.boxColor || '#16A34A';
}

const rawPos = String(rawSubs.position || 'bottom-center').toLowerCase();
let zvidPosition = 'bottom-center';
if (rawPos.includes('top')) zvidPosition = 'top-center';
else if (rawPos.includes('center') && !rawPos.includes('bottom') && !rawPos.includes('mid')) zvidPosition = 'center';

const payload = {
  name: 'world-mysteries-75s',
  duration: 75,
  resolution: 'youtube-short',
  frameRate: 30,
  backgroundColor: '#000000',
  outputFormat: 'mp4',
  visuals: visuals,
  audios: audios,
  subtitle: {
    captions: captions,
    animation: animationType,
    activeWord: activeWordObj,
    font: {
      family: resolvedFontFamily,
      size: Number(rawSubs.fontSize) || 72,
      color: rawSubs.lineColor || (rawSubs.font && rawSubs.font.color) || '#FFFFFF',
      bold: true
    },
    stroke: {
      color: rawSubs.outlineColor || (rawSubs.stroke && rawSubs.stroke.color) || '#000000',
      width: Number(rawSubs.outlineWidth) || (rawSubs.stroke && rawSubs.stroke.width) || 10
    },
    position: zvidPosition,
    maxWordsPerLine: isOneWord ? 1 : (Number(rawSubs.maxWordsPerLine) || 3)
  }
};

return [{
  json: {
    usedZvidKey: currentKey,
    keyIndex: currentKeyIndex,
    payload: payload
  }
}];

// Rotate Zvid On Failure
const staticData = $getWorkflowStaticData('global');
let keys = [];
try {
  keys = $('Config: Zvid Master').first().json.keys || [];
} catch(e) {}

const totalKeys = keys.length;
const firstItem = $input.first() || { json: {} };

if (staticData.zvidAttempts === undefined) {
  staticData.zvidAttempts = 0;
}

staticData.zvidAttempts += 1;

if (staticData.zvidAttempts >= totalKeys) {
  console.log(`All ${totalKeys} Zvid API keys exhausted.`);
  staticData.zvidKeyIndex = 0;
  staticData.zvidAttempts = 0;
  throw new Error('All Zvid API keys exhausted. Please add more keys to Config: Zvid Master.');
}

staticData.zvidKeyIndex = (staticData.zvidKeyIndex || 0) + 1;
console.log(`Zvid Attempt ${staticData.zvidAttempts}/${totalKeys}: Rotating to key index ${staticData.zvidKeyIndex}`);

return [{
  json: {
    retry: true,
    attempt: staticData.zvidAttempts,
    ...firstItem.json
  }
}];

// Init YouTube Resumable Upload (Auto Mode) — ZERO RAM ALLOCATION & EXACT SIZING
const helpers = this.helpers;
async function httpFetch(url, opts = {}) {
  const reqOpts = {
    method: String(opts.method || 'GET').toUpperCase(),
    url,
    headers: opts.headers || {},
    json: false,
    returnFullResponse: true,
    timeout: opts.timeout || 60000
  };
  if (opts.body !== undefined && opts.body !== null) reqOpts.body = opts.body;
  let statusCode = 0;
  let rawHeaders = {};
  let rawBody = '';
  try {
    const r = await helpers.httpRequest(reqOpts);
    statusCode = r.statusCode || 200;
    rawHeaders = r.headers || {};
    rawBody = r.body;
  } catch (err) {
    const resp = (err && (err.response || (err.cause && err.cause.response))) || {};
    statusCode = Number(resp.status || resp.statusCode || err.statusCode || 0) || 0;
    rawHeaders = resp.headers || {};
    rawBody = resp.data !== undefined ? resp.data : (err.message || String(err));
  }
  const asText = () => typeof rawBody === 'string' ? rawBody : (Buffer.isBuffer(rawBody) ? rawBody.toString('utf8') : JSON.stringify(rawBody || ''));
  return {
    ok: statusCode >= 200 && statusCode < 300,
    status: statusCode,
    headers: {
      get: (name) => {
        const want = String(name).toLowerCase();
        for (const k of Object.keys(rawHeaders || {})) {
          if (k.toLowerCase() === want) return rawHeaders[k];
        }
        return null;
      }
    },
    text: async () => asText(),
    json: async () => {
      if (rawBody && typeof rawBody === 'object' && !Buffer.isBuffer(rawBody)) return rawBody;
      try { return JSON.parse(asText()); } catch (e) { return {}; }
    }
  };
}

const item = $input.first();
let binaryMeta = item.binary?.data || Object.values(item.binary || {})[0] || {};
let chatCtx = {};
let splitScenes = {};
let parseStrategy = {};

try { chatCtx = $('Filter: My Chat Only').first().json || {}; } catch(e) {}
try { splitScenes = $('Split Scenes').first().json || {}; } catch(e) {}
try { parseStrategy = $('Parse Strategy Output').first().json || {}; } catch(e) {}

let accessToken = chatCtx.userYouTubeAccessToken;

// 1. Refresh OAuth Token silently if threadId exists
if (chatCtx.threadId) {
  try {
    const refreshRes = await httpFetch('https://bangai.netlify.app/.netlify/functions/refresh-upload-token', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-webhook-secret': 's-vshorts-sec-9a8b7c6d5e4f3a2b1c0'
      },
      body: JSON.stringify({
        threadId: chatCtx.threadId,
        channelId: chatCtx.userYouTubeChannelId || '',
        scope: 'youtube'
      })
    });
    if (refreshRes.ok) {
      const refreshData = await refreshRes.json();
      if (refreshData.accessToken) {
        accessToken = refreshData.accessToken;
      }
    }
  } catch (refreshErr) {
    console.warn('[Init YouTube] Token refresh notice:', refreshErr.message);
  }
}

if (!accessToken) {
  throw new Error('User YouTube OAuth access token is missing');
}

const title = (splitScenes.title || chatCtx.title || chatCtx.rawUserInput || 'Viral YouTube Short').substring(0, 100);
const baseDesc = splitScenes.youtubeDescription || chatCtx.description || '';
const description = baseDesc.includes('#Shorts') ? baseDesc : (baseDesc + '\n\n#Shorts');
const tags = Array.isArray(splitScenes.tags) ? splitScenes.tags : (splitScenes.tags ? splitScenes.tags.split(',') : []);

// Determine privacy
let approvalPrivacy = '';
try {
  const rawWait = $('Wait for Scenes Approval').first().json || {};
  const waitBody = rawWait.body || rawWait.query || rawWait || {};
  approvalPrivacy = String(waitBody.privacyStatus || waitBody.privacy || '').toLowerCase();
} catch (e) {}
const requestedPrivacy = String(approvalPrivacy || chatCtx.privacyStatus || chatCtx.privacy || '').toLowerCase();
const finalPrivacy = ['public', 'private', 'unlisted'].includes(requestedPrivacy) ? requestedPrivacy : 'public';

// Resolve video source URL
let srcUrl = '';
const inputJson = item.json || {};
srcUrl = inputJson.result?.url || inputJson.url || inputJson.videoUrl || '';
if (!srcUrl) {
  try {
    let zvidRes = $('Zvid Status = Done?').first()?.json || {};
    if (!zvidRes.result && !zvidRes.url) zvidRes = $('Poll Zvid Status').first()?.json || {};
    srcUrl = zvidRes.result?.url || zvidRes.url || zvidRes.videoUrl || '';
  } catch (e) {}
}
if (!srcUrl) {
  try {
    const dlJson = $('Download Video').first()?.json || {};
    srcUrl = dlJson.result?.url || dlJson.url || dlJson.videoUrl || '';
  } catch (e) {}
}

// Exact byte sizing: HEAD request provides the exact byte size to the single byte
let bytes = 0;
if (srcUrl) {
  try {
    const headRes = await httpFetch(srcUrl, { method: 'HEAD', timeout: 15000 });
    const cl = headRes.headers.get('content-length');
    if (cl && Number(cl) > 0) bytes = Number(cl);
  } catch (e) {
    console.warn('[Init YouTube] HEAD check notice:', e.message);
  }
}
if (!bytes && binaryMeta.fileSizeBytes && Number(binaryMeta.fileSizeBytes) > 0) {
  bytes = Number(binaryMeta.fileSizeBytes);
}

const mimeType = binaryMeta.mimeType || 'video/mp4';

const metadata = {
  snippet: {
    title: title,
    description: description,
    tags: tags.map(t => t.replace(/[<>]/g, '').trim()).filter(t => t.length > 0).slice(0, 30),
    categoryId: '24',
    defaultLanguage: (parseStrategy.language === 'English') ? 'en' : 'hi'
  },
  status: {
    privacyStatus: finalPrivacy,
    selfDeclaredMadeForKids: false,
    embeddable: true,
    publicStatsViewable: true
  }
};

const initHeaders = {
  'Authorization': 'Bearer ' + accessToken,
  'Content-Type': 'application/json; charset=UTF-8',
  'X-Upload-Content-Type': mimeType
};
if (bytes > 0) {
  initHeaders['X-Upload-Content-Length'] = String(bytes);
}

// Initiate Resumable Upload
const initRes = await httpFetch('https://www.googleapis.com/upload/youtube/v3/videos?uploadType=resumable&part=snippet,status', {
  method: 'POST',
  headers: initHeaders,
  body: JSON.stringify(metadata)
});

if (!initRes.ok) {
  const errText = await initRes.text();
  if (initRes.status === 401 || String(errText).includes('401')) {
    throw new Error('YouTube Upload Failed (401 Unauthorized): Google rejected the OAuth access token. The YouTube connection has expired or was revoked. Please reconnect your YouTube channel on BangAI (https://bangai.netlify.app/#/profile).');
  }
  throw new Error('YouTube Upload Init Failed: ' + errText);
}

const uploadUrl = initRes.headers.get('location');
if (!uploadUrl) {
  throw new Error('YouTube API did not return upload location URL');
}

return [{
  json: {
    uploadUrl: uploadUrl,
    fileSize: bytes,
    srcUrl: srcUrl,
    mimeType: mimeType,
    title: title,
    description: description,
    tags: tags,
    accessToken: accessToken,
    channelTitle: chatCtx.userYouTubeChannelTitle || '',
    channelId: chatCtx.userYouTubeChannelId || '',
    threadId: chatCtx.threadId || ''
  },
  binary: item.binary
}];

// Dynamic User YouTube Upload (Post-Stream Status Verifier & 308 Auto-Recovery)
const helpers = this.helpers;
async function httpFetch(url, opts = {}) {
  const reqOpts = {
    method: String(opts.method || 'GET').toUpperCase(),
    url,
    headers: opts.headers || {},
    json: false,
    returnFullResponse: true,
    timeout: opts.timeout || 20000
  };
  if (opts.body !== undefined && opts.body !== null) reqOpts.body = opts.body;
  let statusCode = 0;
  let rawHeaders = {};
  let rawBody = '';
  try {
    const r = await helpers.httpRequest(reqOpts);
    statusCode = r.statusCode || 200;
    rawHeaders = r.headers || {};
    rawBody = r.body;
  } catch (err) {
    const resp = (err && (err.response || (err.cause && err.cause.response))) || {};
    statusCode = Number(resp.status || resp.statusCode || err.statusCode || 0) || 0;
    rawHeaders = resp.headers || {};
    rawBody = resp.data !== undefined ? resp.data : (err.message || String(err));
  }
  const asText = () => typeof rawBody === 'string' ? rawBody : (Buffer.isBuffer(rawBody) ? rawBody.toString('utf8') : JSON.stringify(rawBody || ''));
  return {
    ok: statusCode >= 200 && statusCode < 300,
    status: statusCode,
    headers: {
      get: (name) => {
        const want = String(name).toLowerCase();
        for (const k of Object.keys(rawHeaders || {})) {
          if (k.toLowerCase() === want) return rawHeaders[k];
        }
        return null;
      }
    },
    text: async () => asText(),
    body: rawBody,
    json: async () => {
      if (rawBody && typeof rawBody === 'object' && !Buffer.isBuffer(rawBody)) return rawBody;
      try { return JSON.parse(asText()); } catch (e) { return {}; }
    }
  };
}

const inputItem = $input.first()?.json || {};
let initData = {};
try { initData = $('Init YouTube Resumable Upload').first()?.json || {}; } catch(e) {}

let videoId = inputItem.id || inputItem.uploadId;
const accessToken = initData.accessToken || inputItem.accessToken;
const title = initData.title || inputItem.title || 'Viral YouTube Short';
const bytes = Number(initData.fileSize || inputItem.fileSize || 0);
const mimeType = initData.mimeType || 'video/mp4';
const channelTitle = initData.channelTitle || inputItem.channelTitle || '';
const srcUrl = initData.srcUrl || '';

// Auto-Recovery: If videoId not directly returned, query Google Resumable Upload Status (handles 308 or socket-end)
if (!videoId && initData.uploadUrl) {
  try {
    const statusRes = await httpFetch(initData.uploadUrl, {
      method: 'PUT',
      headers: {
        'Content-Length': '0',
        'Content-Range': 'bytes */' + (bytes > 0 ? String(bytes) : '*')
      },
      timeout: 15000
    });

    if (statusRes.status === 200 || statusRes.status === 201) {
      const vidJson = await statusRes.json();
      if (vidJson.id) videoId = vidJson.id;
    } else if (statusRes.status === 308 && srcUrl && bytes > 0) {
      const rangeHeader = statusRes.headers.get('range');
      if (rangeHeader) {
        const m = rangeHeader.match(/bytes=0-(\d+)/);
        if (m) {
          const lastByte = parseInt(m[1], 10);
          const nextByte = lastByte + 1;
          const missingBytes = bytes - nextByte;
          if (missingBytes > 0 && missingBytes <= 50 * 1024 * 1024) {
            const sliceRes = await httpFetch(srcUrl, {
              method: 'GET',
              headers: { 'Range': 'bytes=' + nextByte + '-' + (bytes - 1) },
              timeout: 30000
            });
            if (sliceRes.ok) {
              const tailBuffer = typeof sliceRes.body === 'string' ? Buffer.from(sliceRes.body, 'binary') : sliceRes.body;
              const finalPutRes = await httpFetch(initData.uploadUrl, {
                method: 'PUT',
                headers: {
                  'Content-Length': String(tailBuffer.length),
                  'Content-Range': 'bytes ' + nextByte + '-' + (bytes - 1) + '/' + bytes
                },
                body: tailBuffer,
                timeout: 60000
              });
              if (finalPutRes.status === 200 || finalPutRes.status === 201) {
                const finalVid = await finalPutRes.json();
                if (finalVid.id) videoId = finalVid.id;
              }
            }
          }
        }
      }
    }
  } catch (recoverErr) {
    console.warn('[Dynamic User YouTube Upload] Recovery query notice:', recoverErr.message);
  }
}

if (!videoId) {
  const errDesc = inputItem.error?.message || JSON.stringify(inputItem) || 'YouTube Stream Upload Failed';
  return [{
    json: {
      success: false,
      uploadId: null,
      id: null,
      title: title,
      url: '',
      channelTitle: channelTitle,
      userUploaded: false,
      bytesUploaded: 0,
      mimeType: mimeType,
      ytUploadStatus: 'failed',
      ytProcessingStatus: 'failed',
      ytFailureReason: errDesc,
      uploadStatus: 'FAILED',
      uploadError: errDesc
    }
  }];
}

let ytUploadStatus = 'uploaded';
let ytProcessingStatus = 'processing';
let ytFailureReason = null;
let ytRejectionReason = null;

if (accessToken && videoId) {
  try {
    const vRes = await httpFetch('https://www.googleapis.com/youtube/v3/videos?part=status,processingDetails&id=' + videoId, {
      method: 'GET',
      headers: { 'Authorization': 'Bearer ' + accessToken },
      timeout: 15000
    });
    if (vRes.ok) {
      const vJson = await vRes.json();
      const vItem = (vJson.items || [])[0];
      if (vItem) {
        ytUploadStatus = vItem.status?.uploadStatus || ytUploadStatus;
        ytFailureReason = vItem.status?.failureReason || null;
        ytRejectionReason = vItem.status?.rejectionReason || null;
        ytProcessingStatus = vItem.processingDetails?.processingStatus || ytProcessingStatus;
      }
    }
  } catch (e) {}
}

const isDone = (ytUploadStatus === 'processed' || ytProcessingStatus === 'succeeded');

return [{
  json: {
    success: true,
    uploadId: videoId,
    id: videoId,
    title: title,
    url: 'https://youtube.com/shorts/' + videoId,
    channelTitle: channelTitle,
    userUploaded: true,
    bytesUploaded: bytes,
    mimeType: mimeType,
    ytUploadStatus: ytUploadStatus,
    ytProcessingStatus: ytProcessingStatus,
    ytFailureReason: ytFailureReason,
    ytRejectionReason: ytRejectionReason,
    uploadStatus: isDone ? 'UPLOADED' : 'PROCESSING'
  }
}];
